def digest(pw):
    return hashlib.sha256(pw.encode('utf-8')).hexdigest()

def breached(pw):
    return digest(pw) in LEAKED

def weak(pw):
    if len(pw) < 10:
        return True
    classes = 0
    if any(c.islower() for c in pw):
        classes = classes + 1
    if any(c.isupper() for c in pw):
        classes = classes + 1
    if any(c.isdigit() for c in pw):
        classes = classes + 1
    if any(not c.isalnum() for c in pw):
        classes = classes + 1
    return classes < 3

def audit(accounts):
    weak_n = 0
    reused_n = 0
    breached_n = 0
    seen = set()
    for name, pw in accounts:
        if weak(pw):
            weak_n = weak_n + 1
        if pw in seen:
            reused_n = reused_n + 1
        seen.add(pw)
        if breached(pw):
            breached_n = breached_n + 1
    return (weak_n, reused_n, breached_n)

